%[text] # Axial Compressor Design Procedure Ex.
%[text] Station Reference:
%[text] ![](text:image:17d6)
clc; clear; close all;
compMission = dataImport('../Data/GasTurb/comprehensiveMissionPerformanceData.xlsx');
%[text] #### 1: Spcecification
mdot = compMission{'Total Mass Flow W2','RTO'};
PR = compMission{'LPC Inner Pressure Ratio','RTO'};
Pt2 = compMission{'Inlet Pressure P2','RTO'};
Tt2 = compMission{'Inlet Temperature T2','RTO'};
R = 287.0;
eta = 0.9;
%[text] #### 2: Annulus Design
%[text] $A=\\pi r\_{tip}^2(1-(\\frac{H}{T})^2)${"altText":" A=pi\*r\_tip^2\*\[1-(H\/T)^2\])"}
%a
Max2 = 0.5;

%b
alpha2 = 0;

%c
HTR = 0.4;

%d
r_tip = 27/2; % From Estimate, Fan Diameter 27 in
A2 = pi * r_tip^2 * (1 - HTR^2);
blockageIn = 0.99; % 0.99 for inlet, 0.88 for outlet
blockageOut = 0.99; % 0.99 for inlet, 0.88 for outlet
A2 = A2/blockageIn/blockageOut;

%e
M21 = 0.5;
swirl2 = 0;
%use to calculate comp outlet area and  PR and efficiency (to calc temp)

%f choose const tip radius.
%find outlet hub and mid and tip radii.

